def pv(s):
    out = []
    for tok in s.strip().strip("|").split("|"):
        if not tok:
            continue
        x, y, z = tok.split(",")
        out.append((float(x) * SCALE, float(y) * SCALE, float(z) * SCALE))
    return out


def pf(s):
    out = []
    for tok in s.strip().strip("|").split("|"):
        if not tok:
            continue
        out.append(tuple(int(i) for i in tok.split(",")))
    return out


def material(tag):
    name = "gvf_" + tag
    mat = bpy.data.materials.get(name)
    if mat is None:
        col = COLORS[tag]
        mat = bpy.data.materials.new(name)
        mat.use_nodes = True
        bsdf = mat.node_tree.nodes.get("Principled BSDF")
        if bsdf is not None:
            bsdf.inputs["Base Color"].default_value = (*col, 1.0)
        mat.diffuse_color = (*col, 1.0)
    return mat


def build_mesh(name, verts, faces, tag):
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, [], faces)
    me.validate(verbose=False)
    bm = bmesh.new()
    bm.from_mesh(me)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=MERGE_DIST)
    bmesh.ops.dissolve_limit(bm, angle_limit=DISSOLVE_ANGLE,
                             use_dissolve_boundaries=False, verts=bm.verts, edges=bm.edges)
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(me)
    bm.free()
    me.update()
    me.materials.append(material(tag))
    return me


def build_type_meshes():
    types_ = {}
    for defname, parts in SUBBLOCKS.items():
        ms = []
        for (pname, vs, fs, tag) in parts:
            ms.append(build_mesh("%s::%s" % (defname, pname), pv(vs), pf(fs), tag))
        types_[defname] = ms
    return types_


def mat4(R, t):
    return Matrix(((R[0], R[1], R[2], t[0] * SCALE),
                   (R[3], R[4], R[5], t[1] * SCALE),
                   (R[6], R[7], R[8], t[2] * SCALE),
                   (0.0, 0.0, 0.0, 1.0)))


def main():
    coll = bpy.data.collections.get(ROOT_NAME)
    if coll is None:
        coll = bpy.data.collections.new(ROOT_NAME)
        bpy.context.scene.collection.children.link(coll)

    root = bpy.data.objects.new(ROOT_NAME + "_root", None)
    root.empty_display_type = "PLAIN_AXES"
    root.empty_display_size = 150.0 * SCALE
    coll.objects.link(root)

    type_meshes = build_type_meshes()

    counters = {}
    n_obj = 0
    for (defname, R, t) in SCENE:
        k = counters.get(defname, 0) + 1
        counters[defname] = k
        inst = bpy.data.objects.new("%s_%02d" % (defname.replace(" ", ""), k), None)
        inst.empty_display_type = "ARROWS"
        inst.empty_display_size = 40.0 * SCALE
        coll.objects.link(inst)
        inst.parent = root
        inst.matrix_world = mat4(R, t)
        for me in type_meshes[defname]:
            ob = bpy.data.objects.new(me.name.split("::")[-1], me)
            coll.objects.link(ob)
            ob.parent = inst
            n_obj += 1

    print("Built '%s' (no connectors): %d instances, %d leaf objects" % (ROOT_NAME, len(SCENE), n_obj))


if __name__ == "__main__":
    main()
